            "@type": "FAQPage",
            "@id": "https://www.forter.com/#faq",
            "mainEntity": [
                {
                    "@type": "Question",
                    "name": "What does Forter do?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Forter is the trust platform for digital commerce. Submit any customer event — login, signup, checkout, payment, refund, chargeback — and receive an actionable approve/decline/verify decision in under 100ms, built on Forter's identity network (1B+ identities, trillions of transactions across 300+ digital-first merchants including Nordstrom, ASOS, eBay, Priceline, Sephora, and Instacart)."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Who is Forter for?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Digital-first merchants at scale — who need real-time, network-trained fraud and identity decisions across multiple channels (web, native app, voice, agent surfaces, in-store) treated as one user with one risk profile."
                    }
                },
                {
                    "@type": "Question",
                    "name": "How does Forter compare to others?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "First-party honest comparisons live at forter.com/compare. The short version: Forter ships network-trained decisions across the full lifecycle (login, signup, checkout, payment, refund, chargeback) — broader than checkout-only or anti-abuse-only competitors."
                    }
                },
                {
                    "@type": "Question",
                    "name": "How fast is Forter's decision latency?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "p95 ≤ 100ms, p99 ≤ 250ms on decision endpoints. Decisions are synchronous server-to-server; the merchant blocks on the call before completing checkout."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Can my AI agent integrate with Forter?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Yes. Forter publishes an MCP server at mcp.forter.com (Streamable HTTP, OAuth 2.0 + PKCE S256 via portal.forter.com), a REST API at api.forter-secure.com (HTTP Basic + X-Forter-SiteId + Api-Version headers), an OpenAPI 3.x spec, and Web Bot Auth (RFC 9421) signature verification. Compatible with Claude.ai, ChatGPT custom connectors, Gemini extensions, Cursor, Windsurf, and any Streamable-HTTP MCP client. See https://www.forter.com/AGENTS.md."
                    }
                },
                {
                    "@type": "Question",
                    "name": "How does Forter authenticate?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Forter has two auth surfaces. The REST API at api.forter-secure.com uses HTTP Basic with the API key as username and an empty password, plus X-Forter-SiteId and Api-Version headers — credentials are issued at https://portal.forter.com → Integrations → API Credentials. The MCP server at mcp.forter.com uses OAuth 2.0 + PKCE S256 with portal.forter.com as the authorization server (authorization_code + refresh_token grants, no client_credentials, no custom scopes, public client). Discovery: https://www.forter.com/.well-known/oauth-authorization-server."
                    }
                },
                {
                    "@type": "Question",
                    "name": "What does Forter cost?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Forter does not publish list pricing — it is volume-tiered and ACV-negotiated. Sandbox access is self-serve via dynamic client registration; production requires a signed MSA. For a quote, contact https://www.forter.com/contact-us/. Machine-readable pricing summary at https://www.forter.com/pricing.md."
                    }
                },
                {
                    "@type": "Question",
                    "name": "What compliance certifications does Forter hold?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "PCI DSS Level 1, SOC 2 Type II, ISO 27001. GDPR and CCPA compliant. Data residency available in US, EU, and APAC regions, tenant-pinned."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Does Forter support chargeback recovery?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Yes. Submit a chargeback via the dispute API and Forter assembles scheme-specific representment evidence across Visa, Mastercard, Amex, Discover, PayPal, Adyen, Stripe, Worldpay, and Primer. Returns expected win-probability before submission."
                    }
                },
                {
                    "@type": "Question",
                    "name": "How does Forter prevent account takeover?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Login events are evaluated against credential-stuffing patterns, session-hijacking signals, MFA-fatigue heuristics, and a compromised-credentials index. Forter returns forterDecision (APPROVE | DECLINE | VERIFICATION_REQUIRED | NOT_REVIEWED), a correlationId, and — when VERIFICATION_REQUIRED is returned — recommendation + verificationMethod for step-up. After completing the challenge, the merchant reports the outcome back via /authentication-result. Especially effective at loyalty-balance redemptions and stored-payment-method changes."
                    }
                }
            ]
